mod shapes {
    pub trait Shape {
        fn area(&self) -> f64;
    }

    pub mod circle {
        pub struct Circle(pub f64);
        impl super::Shape for Circle {
            fn area(&self) -> f64 {
                3.0 * self.0 * self.0
            }
        }
    }

    pub mod rect {
        pub struct Rect(pub f64, pub f64);
        impl super::Shape for Rect {
            fn area(&self) -> f64 {
                self.0 * self.1
            }
        }
    }
}

